create table if not exists public.webhook_integrations (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, funnel_id text references public.funnels(id) on delete cascade, name text not null, provider text not null default 'custom', endpoint_key text not null unique, secret_hash text not null, status text not null default 'active' check (status in ('active','disabled')), created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create index if not exists webhook_integrations_user_idx on public.webhook_integrations(user_id); create index if not exists webhook_integrations_funnel_idx on public.webhook_integrations(funnel_id); alter table public.webhook_integrations enable row level security; drop policy if exists webhook_integrations_select_own on public.webhook_integrations; create policy webhook_integrations_select_own on public.webhook_integrations for select to authenticated using (user_id=auth.uid()); drop policy if exists webhook_integrations_insert_own on public.webhook_integrations; create policy webhook_integrations_insert_own on public.webhook_integrations for insert to authenticated with check (user_id=auth.uid()); drop policy if exists webhook_integrations_update_own on public.webhook_integrations; create policy webhook_integrations_update_own on public.webhook_integrations for update to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid()); revoke all on public.webhook_integrations from anon, authenticated; grant select,insert,update on public.webhook_integrations to authenticated;